export const SCHEMA = `
    PRAGMA foreign_keys = ON;

    CREATE TABLE IF NOT EXISTS movements (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        order_number TEXT NOT NULL,
        branch TEXT NOT NULL,
        head_number TEXT,
        attachment_number TEXT,
        driver_name TEXT NOT NULL,
        badge_number TEXT,
        mobile TEXT,
        actual_departure_date TEXT,
        departure_time TEXT,
        customer_name TEXT NOT NULL,
        customer_number TEXT,
        destination_from TEXT,
        destination_to TEXT,
        coordinates TEXT,
        payload_type TEXT,
        reporting_terminal TEXT,
        delivery_note_pod TEXT,
        expected_offloading_date TEXT,
        expected_offloading_time TEXT,
        customer_eta TEXT,
        terminal_eta TEXT,
        delay TEXT,
        reason_for_delay TEXT,
        notes_remarks TEXT,
        vehicle_profile TEXT DEFAULT 'heavy_truck_partial',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS tracking (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        movement_id INTEGER NOT NULL,
        tracking_date TEXT NOT NULL,
        location TEXT NOT NULL,
        coordinates TEXT,
        status TEXT NOT NULL,
        remarks TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (movement_id) REFERENCES movements(id) ON DELETE CASCADE
    );

    CREATE INDEX IF NOT EXISTS idx_order_number ON movements(order_number);
    CREATE INDEX IF NOT EXISTS idx_tracking_movement_id ON tracking(movement_id);

    CREATE TABLE IF NOT EXISTS audit_logs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT NOT NULL,
        table_name TEXT NOT NULL,
        record_id TEXT,
        order_number TEXT,
        details TEXT,
        user_agent TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS address_book (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        type TEXT NOT NULL CHECK(type IN ('driver','customer')),
        contact TEXT,
        branch TEXT NOT NULL,
        is_sample INTEGER DEFAULT 0
    );

    CREATE TABLE IF NOT EXISTS branches (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL UNIQUE
    );

    CREATE TABLE IF NOT EXISTS fleet (
        id TEXT PRIMARY KEY,
        type TEXT NOT NULL CHECK(type IN ('head','attachment')),
        branch TEXT NOT NULL,
        description TEXT NOT NULL,
        is_sample INTEGER DEFAULT 0
    );

    CREATE VIEW IF NOT EXISTS latest_tracking AS
    SELECT t1.* FROM tracking t1
    WHERE t1.id = (
        SELECT t2.id FROM tracking t2
        WHERE t2.movement_id = t1.movement_id
        ORDER BY t2.tracking_date DESC, t2.id DESC
        LIMIT 1
    );

    CREATE TABLE IF NOT EXISTS sample_data_registry (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        table_name TEXT NOT NULL,
        row_id INTEGER NOT NULL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        UNIQUE (table_name, row_id)
    );
`;

